// Lit la date (dd/MM/yyyy) du déclencheur ou tombe sur aujourd'hui (UTC).
const j = $input.first().json || {};
const body = j.body && typeof j.body === 'object' && !Array.isArray(j.body) ? j.body : j;
function pad(n){return String(n).padStart(2,'0');}
let dmy = body.date;
if (!/^\d{2}\/\d{2}\/\d{4}$/.test(dmy || '')) {
  const d = new Date();
  dmy = pad(d.getUTCDate()) + '/' + pad(d.getUTCMonth()+1) + '/' + d.getUTCFullYear();
}
const [dd, mm, yyyy] = dmy.split('/');
return [{ json: { dmy, iso: yyyy + '-' + mm + '-' + dd } }];

// Normalise transits + lune vers { date, planets[] } attendu par le site.
const prep = $('Prepare Date').first().json;
const norm360 = (a) => ((a % 360) + 360) % 360;

const trItems = $('HTTP Transits').all().map(i => i.json);
const trRow = trItems.find(r => r && r.planetes) || trItems[0] || {};
const P = (trRow && trRow.planetes) ? trRow.planetes : {};

const moonItems = $('HTTP Moon').all().map(i => i.json);
const moonRow = moonItems.find(r => r && typeof r.date_heure === 'string' && r.date_heure.includes('12:00'))
  || moonItems[moonItems.length - 1] || null;

// 10 classiques + Chiron + Nœuds, + Lilith & astéroïdes (Cérès/Pallas/Junon/Vesta,
// affichés côté site en « vue avancée » uniquement — clés brutes de /transits).
const NAME_MAP = {
  Soleil: 'Soleil', Mercure: 'Mercure', 'Vénus': 'Vénus', Mars: 'Mars',
  Jupiter: 'Jupiter', Saturne: 'Saturne', Uranus: 'Uranus', Neptune: 'Neptune',
  Pluton: 'Pluton', Chiron: 'Chiron', Noeud_Nord: 'Nœud Nord', Noeud_Sud: 'Nœud Sud',
  Lilith: 'Lilith', Ceres: 'Cérès', Pallas: 'Pallas', Junon: 'Junon', Vesta: 'Vesta',
};
const planets = [];
for (const src of Object.keys(NAME_MAP)) {
  const p = P[src];
  if (!p) continue;
  const full = Number(p.longitude_absolue);
  if (!Number.isFinite(full)) continue;
  const nd = Number(p.degre_dans_signe);
  planets.push({
    name: NAME_MAP[src],
    fullDegree: norm360(full),
    normDegree: Number.isFinite(nd) ? nd : ((full % 30) + 30) % 30,
    retro: p.est_retrograde === true || p.est_retrograde === 'True',
    sign: typeof p.signe === 'string' ? p.signe : undefined,
  });
}
if (moonRow && moonRow.lune) {
  const m = moonRow.lune;
  const full = Number(m.longitude_absolue);
  if (Number.isFinite(full)) {
    const nd = Number(m.degre_dans_signe);
    planets.push({
      name: 'Lune',
      fullDegree: norm360(full),
      normDegree: Number.isFinite(nd) ? nd : ((full % 30) + 30) % 30,
      retro: false,
      sign: typeof m.signe === 'string' ? m.signe : undefined,
    });
  }
}
return [{ json: { date: prep.iso, planets, n8nExecutionId: String($execution.id) } }];
